#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
layout(color) uniform half4 amzp_shadowColor;
uniform float amzp_shadowStrength;
uniform float amzp_shadowRange;
layout(color) uniform half4 amzp_midColor;
uniform float amzp_midStrength;
uniform float amzp_midRange;
uniform float amzp_midWidth;
layout(color) uniform half4 amzp_highlightColor;
uniform float amzp_highlightStrength;
uniform float amzp_highlightRange;
uniform float amzp_blendMode;
uniform float amzp_tonerMix;
uniform float amzp_preserveLuminance;
uniform float amzp_contrast;
uniform float amzp_saturation;
uniform float amzp_gamma;
uniform float amzp_overallStrength;
uniform float amzp_tonerOnly;


    const float PI = 3.14159265358979323846;

    float luminance(float3 c){
      return dot(c, float3(0.2126, 0.7152, 0.0722));
    }

    float3 srgbToLinear(float3 c){
      float3 cut = step(float3(0.04045), c);
      return mix(c / 12.92, pow((c + 0.055) / 1.055, float3(2.4)), cut);
    }

    float3 linearToSrgb(float3 c){
      c = max(c, float3(0.0));
      float3 cut = step(float3(0.0031308), c);
      return mix(c * 12.92, 1.055 * pow(c, float3(1.0 / 2.4)) - 0.055, cut);
    }

    float3 applyColorGrade(float3 col, float cont, float sat, float gam){
      float lum = luminance(col);
      col = mix(float3(lum), col, sat);
      col = (col - 0.5) * cont + 0.5;
      col = pow(clamp(col, 0.0001, 1.0), float3(1.0 / max(gam, 0.001)));
      return clamp(col, 0.0, 1.0);
    }

    float3 applyToner(
      float3 col,
      float lum,
      float3 shadCol, float shadStr, float shadRange,
      float3 midCol,  float midStr,  float midCtr, float midW,
      float3 hiCol,   float hiStr,   float hiRange
    ){
      float shadowMask    = smoothstep(shadRange, 0.0, lum);
      float highlightMask = smoothstep(hiRange, 1.0, lum);
      float midMask       = smoothstep(0.0, midW, lum - (midCtr - midW))
                          * smoothstep(0.0, midW, (midCtr + midW) - lum);

      float3 toned = col;
      toned = mix(toned, shadCol, shadowMask    * shadStr);
      toned = mix(toned, midCol,  midMask       * midStr);
      toned = mix(toned, hiCol,   highlightMask * hiStr);

      return toned;
    }

    float3 blendOverlay(float3 base, float3 blend){
      float3 low  = 2.0 * base * blend;
      float3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
      return mix(low, high, step(0.5, base));
    }

    void amzRender(){

      float2 uv = amzScreenNorm();

      float4 src = amzTexture(0, uv);
      float3 col = src.rgb;

      float3 colLin = srgbToLinear(col);
      float lum = luminance(colLin);
      lum = pow(clamp(lum, 0.0, 1.0), 1.0 / max(amzp_gamma, 0.001));

      float3 toned = applyToner(
        col,
        lum,
        amzp_shadowColor.rgb,    amzp_shadowStrength,    amzp_shadowRange,
        amzp_midColor.rgb,       amzp_midStrength,       amzp_midRange,    amzp_midWidth,
        amzp_highlightColor.rgb, amzp_highlightStrength, amzp_highlightRange
      );

      float3 result;
      float bmf = float(int(amzp_blendMode));

      if(bmf < 1.5){
        float tonedLum = luminance(srgbToLinear(toned));
        result = toned;
        if((amzp_preserveLuminance>0.5)){
          float origLum = luminance(colLin);
          float scale = origLum / max(tonedLum, 0.0001);
          result = clamp(toned * scale, 0.0, 1.0);
        }
      } else if(bmf < 2.5){
        float origLum = luminance(colLin);
        float3 tonedLin = srgbToLinear(toned);
        float tonedLumV = luminance(tonedLin);
        float3 chromaToned = tonedLin / max(tonedLumV, 0.0001);
        result = linearToSrgb(clamp(chromaToned * origLum, 0.0, 1.0));
      } else {
        result = blendOverlay(col, toned);
      }

      result = mix(result, toned, amzp_tonerMix);
      result = applyColorGrade(result, amzp_contrast, amzp_saturation, 1.0);
      result = mix(col, result, amzp_overallStrength);

      if((amzp_tonerOnly>0.5)){
        float lumOnly = luminance(srgbToLinear(col));
        float shadowM    = smoothstep(amzp_shadowRange, 0.0, lumOnly);
        float highlightM = smoothstep(amzp_highlightRange, 1.0, lumOnly);
        float midM       = smoothstep(0.0, amzp_midWidth, lumOnly - (amzp_midRange - amzp_midWidth))
                         * smoothstep(0.0, amzp_midWidth, (amzp_midRange + amzp_midWidth) - lumOnly);
        float3 zones = shadowM * float3(0.2, 0.0, 0.8)
                   + midM    * float3(0.0, 0.8, 0.2)
                   + highlightM * float3(0.9, 0.8, 0.0);
        amzOutput = float4(clamp(zones, 0.0, 1.0), src.a);
        return;
      }

      amzOutput = float4(result, src.a);
    }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

